'use strict';
(()=>{const el=(t,text,cls)=>{const n=document.createElement(t);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;},check=r=>{if(r.error)throw Error(r.error.message);return r.data;};async function render({root,team,api,addForm}){root.append(el('h1','Spreadsheets'),el('p','Open the exact spreadsheet tab for your current work. Google controls access to the contents.','portal-description'));const saved=check(await api.db.from('team_resources').select('*').eq('team_id',team).eq('kind','spreadsheet').eq('archived',false).order('title')),library=GuhuzaTeams.allowed(team,'training')?await GuhuzaLearning.workspace(api,team):{catalog:[]},links=[];for(const row of saved||[])links.push({...row,label:row.title});for(const item of library.catalog||[])if(item.kind==='tool'&&item.allowed)for(const ref of item.links||[])if(ref.url&&/docs\.google\.com\/spreadsheets\//.test(ref.url))links.push({id:item.id,label:item.title,url:ref.url,description:item.access_note,location_note:item.location_note,fromLibrary:true});const unique=[...new Map(links.map(x=>[x.url,x])).values()],label=el('label','Find a spreadsheet','portal-field'),search=el('input');search.type='search';label.append(search);root.append(label);const list=el('div',undefined,'sheet-card-grid');root.append(list);function draw(){list.replaceChildren();const rows=unique.filter(x=>(x.label+' '+x.description+' '+x.location_note).toLowerCase().includes(search.value.toLowerCase()));for(const row of rows){const card=el('article',undefined,'learning-card sheet-block'),a=el('a','Open spreadsheet tab','learning-video-link');a.href=row.url;a.target='_blank';a.rel='noopener noreferrer';const icon=el('span','▦','resource-block-icon');icon.setAttribute('aria-hidden','true');card.append(icon,el('h2',row.label),el('p',row.location_note||row.description||'Shared team spreadsheet'),a);if(!row.fromLibrary&&GuhuzaTeams.isAdmin(team)){const edit=el('button','Edit spreadsheet');edit.onclick=()=>{if(card.querySelector('form'))return;const form=el('form',undefined,'portal-form'),inputs={};for(const [key,title,type]of [['title','Spreadsheet title','text'],['description','Description','textarea'],['url','Spreadsheet URL','url']]){const label=el('label',title),input=el(type==='textarea'?'textarea':'input');if(type!=='textarea')input.type=type;input.value=row[key]||'';input.required=key!=='description';input.maxLength=key==='title'?160:key==='url'?4000:5000;label.append(input);form.append(label);inputs[key]=input;}const save=el('button','Save spreadsheet','primary'),cancel=el('button','Cancel'),status=el('p',undefined,'learning-note');save.type='submit';cancel.type='button';status.setAttribute('role','status');cancel.onclick=()=>{form.remove();edit.disabled=false;};form.append(save,cancel,status);card.append(form);edit.disabled=true;form.onsubmit=async event=>{event.preventDefault();save.disabled=true;cancel.disabled=true;try{const url=new URL(inputs.url.value.trim());if(url.protocol!=='https:')throw Error('Use a secure HTTPS spreadsheet URL.');const title=inputs.title.value.trim();if(!title)throw Error('Enter a spreadsheet title.');const updated={title,description:inputs.description.value.trim(),url:url.href};const result=await api.db.from('team_resources').update(updated).eq('id',row.id).eq('team_id',team).eq('kind','spreadsheet').select('id').single();check(result);Object.assign(row,updated,{label:title});draw();}catch(e){status.textContent='Not saved: '+e.message;save.disabled=false;cancel.disabled=false;}};};card.append(edit);}if(row.fromLibrary&&GuhuzaTeams.isAdmin(team)){const edit=el('button','Edit this destination');edit.onclick=()=>GuhuzaTeams.open({view:'tools',team,learningItem:row.id});card.append(edit);}list.append(card);}if(!rows.length)list.append(el('p','No matching spreadsheet links. A team admin can add one below.','learning-note'));}search.oninput=draw;draw();if(GuhuzaTeams.isAdmin(team)){root.append(el('h2','Add a spreadsheet destination'),el('p','Paste a full Google Sheets URL including #gid= for a specific tab, and &range= when a starting cell is useful.','learning-note'));addForm(root,'links');}}
window.GuhuzaSheets={render};})();
